"use client";

import { useEffect, useState, useMemo, useCallback } from "react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import {
  ArrowLeft, Loader2, CalendarDays, Clock, MapPin, CheckCircle2,
  XCircle, AlertCircle, RefreshCw, Package, User, Shield, MessageSquare,
} from "lucide-react";
import toast from "react-hot-toast";
import { bookingService } from "@/services/booking";
import { slotService, Slot } from "@/services/provider";
import { messagingService } from "@/services/messaging";
import { Booking, BookingStatus, BookingStatusEntry } from "@/types/booking.types";
import { getErrorMessage } from "@/utils/errorHandler";

const STATUS_ORDER: BookingStatus[] = ["pending", "confirmed", "accepted", "in_progress", "completed"];

const STATUS_META: Record<BookingStatus, { icon: typeof CheckCircle2; color: string; label: string }> = {
  pending: { icon: Clock, color: "text-amber-500", label: "Pending" },
  confirmed: { icon: CheckCircle2, color: "text-blue-500", label: "Confirmed" },
  accepted: { icon: CheckCircle2, color: "text-indigo-500", label: "Accepted" },
  in_progress: { icon: RefreshCw, color: "text-purple-500", label: "In Progress" },
  completed: { icon: CheckCircle2, color: "text-emerald-500", label: "Completed" },
  cancelled: { icon: XCircle, color: "text-red-500", label: "Cancelled" },
  rejected: { icon: XCircle, color: "text-red-500", label: "Rejected" },
};

function formatDate(iso: string) {
  return new Intl.DateTimeFormat("en-IN", { weekday: "long", day: "numeric", month: "long", year: "numeric" }).format(new Date(iso));
}

function formatDateTime(iso: string) {
  return new Intl.DateTimeFormat("en-IN", { day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso));
}

function getNext7Days(): string[] {
  const days: string[] = [];
  const d = new Date();
  d.setDate(d.getDate() + 1); // start from tomorrow for reschedule
  for (let i = 0; i < 7; i++) {
    days.push(d.toISOString().slice(0, 10));
    d.setDate(d.getDate() + 1);
  }
  return days;
}

export default function BookingDetailsPage() {
  const params = useParams<{ id: string }>();
  const router = useRouter();
  const id = params?.id ?? "";

  const [booking, setBooking] = useState<Booking | null>(null);
  const [loading, setLoading] = useState(true);

  // Reschedule state
  const [showReschedule, setShowReschedule] = useState(false);
  const [rescheduleDate, setRescheduleDate] = useState("");
  const [rescheduleSlots, setRescheduleSlots] = useState<Slot[]>([]);
  const [slotsLoading, setSlotsLoading] = useState(false);
  const [rescheduleLoading, setRescheduleLoading] = useState(false);

  // Cancel state
  const [showCancel, setShowCancel] = useState(false);
  const [cancelReason, setCancelReason] = useState("");
  const [cancelLoading, setCancelLoading] = useState(false);

  const fetchBooking = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    try {
      const r = await bookingService.getById(id);
      setBooking(r.data.data);
    } catch (e) {
      toast.error(getErrorMessage(e) || "Failed to load booking");
    } finally {
      setLoading(false);
    }
  }, [id]);

  useEffect(() => { fetchBooking(); }, [fetchBooking]);

  const providerId = useMemo(() => {
    if (!booking) return null;
    return typeof booking.providerId === "object" ? booking.providerId._id : booking.providerId;
  }, [booking]);

  const canReschedule = useMemo(() => {
    if (!booking) return false;
    if (["cancelled", "completed", "rejected"].includes(booking.bookingStatus)) return false;
    const bookingTime = new Date(`${booking.date}T${booking.startTime}:00`);
    return bookingTime.getTime() - Date.now() > 24 * 60 * 60 * 1000;
  }, [booking]);

  const canCancel = useMemo(() => {
    if (!booking) return false;
    return !["cancelled", "completed"].includes(booking.bookingStatus);
  }, [booking]);

  // Fetch slots for reschedule
  useEffect(() => {
    if (!showReschedule || !providerId || !rescheduleDate) return;
    let c = false;
    setSlotsLoading(true);
    slotService.getAvailable(providerId, rescheduleDate)
      .then((r) => { if (!c) setRescheduleSlots(r.data.data); })
      .catch(() => { if (!c) setRescheduleSlots([]); })
      .finally(() => { if (!c) setSlotsLoading(false); });
    return () => { c = true; };
  }, [showReschedule, providerId, rescheduleDate]);

  const handleReschedule = async (slotId: string) => {
    setRescheduleLoading(true);
    try {
      const r = await bookingService.reschedule(id, slotId);
      setBooking(r.data.data);
      setShowReschedule(false);
      toast.success("Booking rescheduled successfully");
    } catch (e) {
      toast.error(getErrorMessage(e) || "Failed to reschedule");
    } finally {
      setRescheduleLoading(false);
    }
  };

  const handleCancel = async () => {
    setCancelLoading(true);
    try {
      const r = await bookingService.cancel(id, cancelReason || undefined);
      setBooking(r.data.data);
      setShowCancel(false);
      toast.success("Booking cancelled");
    } catch (e) {
      toast.error(getErrorMessage(e) || "Failed to cancel");
    } finally {
      setCancelLoading(false);
    }
  };

  if (loading) {
    return <div className="flex min-h-screen items-center justify-center"><Loader2 size={28} className="animate-spin text-indigo-500" /></div>;
  }

  if (!booking) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center">
        <AlertCircle size={32} className="text-slate-400 mb-2" />
        <p className="font-bold text-slate-600">Booking not found</p>
        <Link href="/bookings" className="mt-3 text-sm font-bold text-indigo-600 hover:underline">Back to bookings</Link>
      </div>
    );
  }

  const svc = typeof booking.serviceId === "object" ? booking.serviceId : null;
  const prov = typeof booking.providerId === "object" ? booking.providerId : null;
  const meta = STATUS_META[booking.bookingStatus];
  const dates = getNext7Days();

  return (
    <div className="mx-auto w-full max-w-4xl fade-up">
        <button onClick={() => router.back()} className="mb-4 inline-flex items-center gap-1 text-sm font-semibold text-slate-500 hover:text-indigo-600">
          <ArrowLeft size={14} /> Back
        </button>

        {/* Header */}
        <div className="rounded-[18px] border border-slate-200 bg-white p-4 sm:p-5">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-xs text-slate-500">Booking ID</p>
              <p className="font-mono text-sm font-bold text-slate-900">{booking._id.slice(-8).toUpperCase()}</p>
            </div>
            <span className={`rounded-full px-3 py-1 text-xs font-bold uppercase ${meta.color} bg-opacity-10`} style={{ backgroundColor: "currentColor", WebkitBackgroundClip: "unset", color: "inherit" }}>
              <span className={`inline-flex items-center gap-1 ${meta.color}`}>
                <meta.icon size={12} /> {meta.label}
              </span>
            </span>
          </div>

          {/* Service info */}
          <div className="mt-4 flex gap-4">
            {svc?.images?.[0] && (
              <div className="hidden sm:block h-20 w-20 shrink-0 rounded-xl overflow-hidden bg-slate-100">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={svc.images[0]} alt="" className="h-full w-full object-cover" />
              </div>
            )}
            <div>
              <h1 className="text-xl font-black text-slate-950">{svc?.name || "Service"}</h1>
              <p className="mt-1 text-sm text-slate-500">{svc ? `${svc.duration} min · ₹${svc.price}` : ""}</p>
            </div>
          </div>
        </div>

        {/* Details grid */}
        <div className="mt-4 grid gap-4 sm:grid-cols-2">
          <div className="rounded-[18px] border border-slate-200 bg-white p-4">
            <p className="text-xs font-bold uppercase text-slate-500 mb-2 flex items-center gap-1"><CalendarDays size={12} /> Date & Time</p>
            <p className="font-bold text-slate-900">{formatDate(booking.date)}</p>
            <p className="text-sm text-slate-600">{booking.startTime} – {booking.endTime}</p>
          </div>

          <div className="rounded-[18px] border border-slate-200 bg-white p-4">
            <p className="text-xs font-bold uppercase text-slate-500 mb-2 flex items-center gap-1"><MapPin size={12} /> Address</p>
            <p className="font-bold text-slate-900">{booking.address.street}</p>
            <p className="text-sm text-slate-600">{booking.address.city}, {booking.address.state} {booking.address.zip}</p>
          </div>

          <div className="rounded-[18px] border border-slate-200 bg-white p-4">
            <p className="text-xs font-bold uppercase text-slate-500 mb-2 flex items-center gap-1"><User size={12} /> Provider</p>
            <p className="font-bold text-slate-900">{prov?.businessName || prov?.name || "—"}</p>
            {prov?.phone && <p className="text-sm text-slate-600">{prov.phone}</p>}
          </div>

          <div className="rounded-[18px] border border-slate-200 bg-white p-4">
            <p className="text-xs font-bold uppercase text-slate-500 mb-2 flex items-center gap-1"><Shield size={12} /> Payment</p>
            <p className="text-2xl font-black text-indigo-600">₹{booking.amount}</p>
            <p className="text-xs text-slate-500 capitalize">Status: {booking.paymentStatus}</p>
          </div>
        </div>

        {/* Status Timeline */}
        <div className="mt-4 rounded-[18px] border border-slate-200 bg-white p-4 sm:p-5">
          <h2 className="text-sm font-black text-slate-900 mb-4">Status Timeline</h2>
          <div className="space-y-0">
            {booking.statusHistory.map((entry, i) => {
              const m = STATUS_META[entry.status] || STATUS_META.pending;
              const Icon = m.icon;
              return (
                <div key={i} className="flex gap-3">
                  <div className="flex flex-col items-center">
                    <div className={`flex h-7 w-7 items-center justify-center rounded-full bg-white border-2 ${m.color.replace("text-", "border-")}`}>
                      <Icon size={14} className={m.color} />
                    </div>
                    {i < booking.statusHistory.length - 1 && <div className="w-px flex-1 bg-slate-200 my-1" />}
                  </div>
                  <div className="pb-4">
                    <p className="font-bold text-slate-900 text-sm capitalize">{entry.status.replace("_", " ")}</p>
                    <p className="text-xs text-slate-500">{formatDateTime(entry.at)}</p>
                    {entry.note && <p className="text-xs text-slate-600 mt-0.5 italic">{entry.note}</p>}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Timestamps */}
        <div className="mt-4 rounded-[18px] border border-slate-200 bg-white p-4 flex flex-wrap gap-6 text-xs text-slate-500">
          <span>Created: {formatDateTime(booking.createdAt)}</span>
          <span>Updated: {formatDateTime(booking.updatedAt)}</span>
        </div>

        {/* Actions */}
        {(canReschedule || canCancel) && (
          <div className="mt-4 flex gap-3">
            {canReschedule && (
              <button onClick={() => { setShowReschedule(true); setRescheduleDate(dates[0]); }} className="flex-1 rounded-xl border border-indigo-200 bg-indigo-50 py-3 text-sm font-bold text-indigo-700 hover:bg-indigo-100 flex items-center justify-center gap-2">
                <RefreshCw size={14} /> Reschedule
              </button>
            )}
            {canCancel && (
              <button onClick={() => setShowCancel(true)} className="flex-1 rounded-xl border border-red-200 bg-red-50 py-3 text-sm font-bold text-red-700 hover:bg-red-100 flex items-center justify-center gap-2">
                <XCircle size={14} /> Cancel
              </button>
            )}
          </div>
        )}

        {/* Message Provider */}
        {providerId && (
          <div className="mt-4">
            <button
              onClick={async () => {
                try {
                  await messagingService.getOrCreateConversation({ providerId: providerId!, bookingId: id, serviceId: typeof booking.serviceId === "object" ? booking.serviceId._id : booking.serviceId });
                  router.push("/messages");
                } catch (e) {
                  toast.error(getErrorMessage(e) || "Failed to start conversation");
                }
              }}
              className="w-full rounded-xl border border-indigo-200 bg-indigo-50 py-3 text-sm font-bold text-indigo-700 hover:bg-indigo-100 flex items-center justify-center gap-2 transition"
            >
              <MessageSquare size={14} /> Message Provider
            </button>
          </div>
        )}

        {/* Reschedule Modal */}
        {showReschedule && (
          <div className="fixed inset-0 z-[10000] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setShowReschedule(false)} />
            <div className="relative bg-white rounded-2xl shadow-2xl p-6 w-full max-w-lg z-10 max-h-[90vh] overflow-y-auto">
              <h2 className="text-lg font-black text-slate-900 mb-1">Reschedule Booking</h2>
              <p className="text-sm text-slate-500 mb-4">Choose a new date and time slot</p>

              {/* Date picker */}
              <div className="flex gap-2 overflow-x-auto pb-3 mb-4">
                {dates.map((d) => (
                  <button key={d} onClick={() => setRescheduleDate(d)} className={`shrink-0 rounded-lg px-3 py-2 text-center transition ${d === rescheduleDate ? "bg-indigo-600 text-white" : "border border-slate-200 text-slate-600 hover:border-indigo-300"}`}>
                    <p className="text-[10px] font-bold uppercase">{new Intl.DateTimeFormat("en", { weekday: "short" }).format(new Date(d))}</p>
                    <p className="text-sm font-black">{new Date(d).getDate()}</p>
                  </button>
                ))}
              </div>

              {/* Slots */}
              {slotsLoading ? (
                <div className="py-6 text-center"><Loader2 size={20} className="mx-auto animate-spin text-indigo-500" /></div>
              ) : rescheduleSlots.length === 0 ? (
                <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center">
                  <p className="font-bold text-slate-600">No slots available</p>
                  <p className="text-xs text-slate-500 mt-1">Try another date</p>
                </div>
              ) : (
                <div className="flex flex-wrap gap-2">
                  {rescheduleSlots.map((slot) => (
                    <button key={slot._id} onClick={() => handleReschedule(slot._id)} disabled={rescheduleLoading} className="rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-2 text-sm font-bold text-emerald-700 hover:bg-emerald-100 disabled:opacity-50">
                      {slot.startTime} – {slot.endTime}
                    </button>
                  ))}
                </div>
              )}

              <button onClick={() => setShowReschedule(false)} className="mt-4 w-full rounded-xl border border-slate-200 py-2.5 text-sm font-bold text-slate-600 hover:bg-slate-50">Cancel</button>
            </div>
          </div>
        )}

        {/* Cancel Modal */}
        {showCancel && (
          <div className="fixed inset-0 z-[10000] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setShowCancel(false)} />
            <div className="relative bg-white rounded-2xl shadow-2xl p-6 w-full max-w-md z-10">
              <h2 className="text-lg font-black text-slate-900 mb-1">Cancel Booking</h2>
              <p className="text-sm text-slate-500 mb-4">Are you sure? This action cannot be undone.</p>

              <textarea
                placeholder="Reason for cancellation (optional)"
                value={cancelReason}
                onChange={(e) => setCancelReason(e.target.value)}
                rows={3}
                className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-red-300 resize-none"
              />

              <div className="mt-4 flex gap-3">
                <button onClick={() => setShowCancel(false)} className="flex-1 rounded-xl border border-slate-200 py-2.5 text-sm font-bold text-slate-600 hover:bg-slate-50">Keep Booking</button>
                <button onClick={handleCancel} disabled={cancelLoading} className="flex-1 rounded-xl bg-red-600 py-2.5 text-sm font-bold text-white hover:bg-red-700 disabled:opacity-50 flex items-center justify-center gap-2">
                  {cancelLoading && <Loader2 size={14} className="animate-spin" />} Confirm Cancel
                </button>
              </div>
            </div>
          </div>
        )}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  CalendarDays, Clock, MapPin, Search, ChevronLeft, ChevronRight,
  Package, Sparkles,
} from "lucide-react";
import toast from "react-hot-toast";
import { bookingService } from "@/services/booking";
import { Booking, BookingStatus } from "@/types/booking.types";
import { getErrorMessage } from "@/utils/errorHandler";

const TABS: { label: string; statuses: BookingStatus[] }[] = [
  { label: "Upcoming", statuses: ["confirmed", "accepted"] },
  { label: "Pending", statuses: ["pending"] },
  { label: "In Progress", statuses: ["in_progress"] },
  { label: "Completed", statuses: ["completed"] },
  { label: "Cancelled", statuses: ["cancelled", "rejected"] },
];

const STATUS_COLORS: Record<BookingStatus, string> = {
  pending: "bg-amber-50 text-amber-700 border border-amber-100",
  confirmed: "bg-blue-50 text-blue-700 border border-blue-100",
  accepted: "bg-purple-50 text-purple-700 border border-purple-100",
  in_progress: "bg-violet-50 text-violet-700 border border-violet-100",
  completed: "bg-emerald-50 text-emerald-700 border border-emerald-100",
  cancelled: "bg-red-50 text-red-700 border border-red-100",
  rejected: "bg-red-50 text-red-700 border border-red-100",
};

function formatDate(iso: string) {
  return new Intl.DateTimeFormat("en-IN", { weekday: "short", day: "numeric", month: "short", year: "numeric" }).format(new Date(iso));
}

export default function MyBookingsPage() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState(0);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  const limit = 10;
  const currentStatuses = TABS[activeTab].statuses;

  const fetchBookings = useCallback(async (status: BookingStatus[], p: number) => {
    setLoading(true);
    try {
      const r = await bookingService.getMyBookings({ status: status[0], page: p, limit });
      setBookings(r.data.data.items);
      setTotal(r.data.data.total);
    } catch (e) {
      toast.error(getErrorMessage(e) || "Failed to load bookings");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchBookings(currentStatuses, page);
  }, [activeTab, page, fetchBookings, currentStatuses]);

  const handleTabChange = (index: number) => {
    setActiveTab(index);
    setPage(1);
  };

  const filtered = search
    ? bookings.filter((b) => {
        const svc = typeof b.serviceId === "object" ? b.serviceId.name : "";
        const prov = typeof b.providerId === "object" ? (b.providerId.businessName || b.providerId.name) : "";
        const q = search.toLowerCase();
        return svc.toLowerCase().includes(q) || prov.toLowerCase().includes(q) || b._id.includes(q);
      })
    : bookings;

  const totalPages = Math.ceil(total / limit);

  return (
    <div className="mx-auto w-full max-w-5xl fade-up">
        <div className="mb-5">
          <h1 className="text-2xl font-extrabold text-slate-950 tracking-tight">My Bookings</h1>
          <p className="mt-1 text-sm text-slate-500">Track and manage your service bookings</p>
        </div>

        {/* Tabs */}
        <div className="flex gap-1 overflow-x-auto border-b border-slate-200/60 pb-px mb-4">
          {TABS.map((tab, i) => (
            <button key={tab.label} onClick={() => handleTabChange(i)} className={`shrink-0 px-4 py-2.5 text-sm font-bold transition-all border-b-[2.5px] rounded-t-lg ${i === activeTab ? "border-[var(--primary)] text-[var(--primary)] bg-purple-50/50" : "border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50"}`}>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Search */}
        <div className="relative mb-5">
          <Search size={17} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            placeholder="Search by service, provider, or booking ID..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-2xl border border-slate-200/80 bg-white pl-12 pr-4 py-3 text-sm font-medium outline-none focus:border-purple-400 focus:ring-4 focus:ring-purple-500/8 shadow-sm transition-all"
          />
        </div>

        {/* Content */}
        {loading ? (
          <div className="space-y-4">
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="rounded-[18px] border border-slate-100 bg-white p-4 sm:p-5">
                <div className="flex gap-4">
                  <div className="hidden sm:block skeleton h-20 w-20 rounded-xl shrink-0" />
                  <div className="flex-1 space-y-3">
                    <div className="flex justify-between">
                      <div className="skeleton h-4 w-40 rounded-lg" />
                      <div className="skeleton h-5 w-18 rounded-full" />
                    </div>
                    <div className="skeleton h-3.5 w-28 rounded-lg" />
                    <div className="skeleton h-3.5 w-56 rounded-lg" />
                    <div className="skeleton h-4 w-20 rounded-lg" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : filtered.length === 0 ? (
          <div className="rounded-[18px] border-2 border-dashed border-slate-200 bg-white p-10 text-center">
            <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-purple-50">
              <Package size={32} className="text-purple-400" />
            </div>
            <p className="font-extrabold text-slate-700 text-xl">No bookings found</p>
            <p className="mt-2 text-sm text-slate-500">{search ? "Try a different search term." : "Book a service to get started."}</p>
            {!search && (
              <Link href="/dashboard" className="mt-6 inline-flex items-center gap-2 rounded-[14px] bg-gradient-to-r from-[#6D28FF] to-[#8B5CF6] px-6 py-3 text-sm font-bold text-white shadow-lg shadow-purple-500/20 hover:shadow-xl hover:-translate-y-0.5 transition-all">
                <Sparkles size={14} /> Browse services
              </Link>
            )}
          </div>
        ) : (
          <div className="space-y-4 stagger">
            {filtered.map((b) => {
              const svc = typeof b.serviceId === "object" ? b.serviceId : null;
              const prov = typeof b.providerId === "object" ? b.providerId : null;
              return (
                <Link key={b._id} href={`/bookings/${b._id}`} className="block bg-white rounded-[18px] border border-slate-100/80 p-4 sm:p-5 hover:shadow-[0_16px_48px_rgba(109,40,255,0.06)] hover:-translate-y-1 hover:border-purple-200/50 transition-all duration-300">
                  <div className="flex gap-4">
                    <div className="hidden sm:block h-20 w-20 shrink-0 rounded-xl bg-slate-50 overflow-hidden border border-slate-100">
                      {svc?.images?.[0] ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img src={svc.images[0]} alt="" className="h-full w-full object-cover" />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center text-slate-200"><Package size={24} /></div>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <div>
                          <p className="font-extrabold text-slate-900 truncate text-[0.95rem]">{svc?.name || "Service"}</p>
                          <p className="text-xs text-slate-500 mt-0.5 font-medium">{prov?.businessName || prov?.name || "Provider"}</p>
                        </div>
                        <span className={`shrink-0 rounded-full px-3 py-1 text-[10px] font-bold uppercase ${STATUS_COLORS[b.bookingStatus]}`}>
                          {b.bookingStatus.replace("_", " ")}
                        </span>
                      </div>
                      <div className="mt-3 flex flex-wrap items-center gap-3 text-xs text-slate-500 font-medium">
                        <span className="inline-flex items-center gap-1.5"><CalendarDays size={12} className="text-[var(--primary)]" /> {formatDate(b.date)}</span>
                        <span className="inline-flex items-center gap-1.5"><Clock size={12} className="text-[var(--primary)]" /> {b.startTime} – {b.endTime}</span>
                        <span className="inline-flex items-center gap-1.5"><MapPin size={12} className="text-[var(--primary)]" /> {b.address.city}</span>
                      </div>
                      <div className="mt-3 flex items-center justify-between">
                        <p className="text-base font-extrabold text-[var(--primary)]">₹{b.amount}</p>
                        <p className="text-[10px] text-slate-400 font-semibold">ID: {b._id.slice(-8).toUpperCase()}</p>
                      </div>
                    </div>
                  </div>
                </Link>
              );
            })}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="mt-8 flex items-center justify-center gap-4">
            <button onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page === 1} className="rounded-xl border border-slate-200 p-2.5 disabled:opacity-30 hover:bg-slate-50 hover:border-purple-200 transition-all"><ChevronLeft size={16} /></button>
            <span className="text-sm font-bold text-slate-600">Page {page} of {totalPages}</span>
            <button onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={page === totalPages} className="rounded-xl border border-slate-200 p-2.5 disabled:opacity-30 hover:bg-slate-50 hover:border-purple-200 transition-all"><ChevronRight size={16} /></button>
          </div>
        )}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useSelector } from "react-redux";
import {
  ArrowRight, Star, Sparkles, BadgeCheck,
  MapPin, Search,
} from "lucide-react";
import { RootState } from "@/store";
import { categoryService } from "@/services/category";
import { providerService } from "@/services/provider";
import { Category } from "@/types/category.types";
import { PublicProvider } from "@/types/provider.types";
import { getErrorMessage } from "@/utils/errorHandler";

const categoryGradients = [
  "from-blue-500 to-cyan-400",
  "from-violet-500 to-purple-400",
  "from-amber-500 to-orange-400",
  "from-emerald-500 to-teal-400",
  "from-rose-500 to-pink-400",
  "from-indigo-500 to-blue-400",
];

const SEARCH_EXAMPLES = [
  "Search AC Repair...",
  "Search Electrician...",
  "Search Cleaning Services...",
  "Search Painting Services...",
  "Search Plumbing...",
];

const renderCategoryIcon = (category: Category) => {
  if (!category.icon) return category.name.charAt(0).toUpperCase();
  if (category.icon.startsWith("http") || category.icon.startsWith("/")) {
    // eslint-disable-next-line @next/next/no-img-element
    return <img src={category.icon} alt="" className="w-8 h-8 object-contain" />;
  }
  return category.icon;
};

export default function DashboardPage() {
  const router = useRouter();
  const { user } = useSelector((state: RootState) => state.auth);
  const location = useSelector((state: RootState) => state.location);
  const [categories, setCategories] = useState<Category[]>([]);
  const [providers, setProviders] = useState<PublicProvider[]>([]);
  const [loadingData, setLoadingData] = useState(true);
  const [dataError, setDataError] = useState("");

  const [searchQuery, setSearchQuery] = useState("");
  const [placeholderIdx, setPlaceholderIdx] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setPlaceholderIdx((i) => (i + 1) % SEARCH_EXAMPLES.length), 2800);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    let active = true;
    const load = async () => {
      try {
        setLoadingData(true);
        setDataError("");
        const providerParams: Record<string, any> = {};
        if (location.isSet && location.latitude && location.longitude) {
          providerParams.latitude = location.latitude;
          providerParams.longitude = location.longitude;
          providerParams.radius = 15;
        }
        const [categoryRes, providerRes] = await Promise.all([
          categoryService.getAll(),
          providerService.getPublicProviders(providerParams),
        ]);
        if (!active) return;
        setCategories(Array.isArray(categoryRes.data.data) ? categoryRes.data.data : []);
        setProviders(Array.isArray(providerRes.data.data) ? providerRes.data.data : []);
      } catch (err) {
        if (active) setDataError(getErrorMessage(err) || "Failed to load dashboard data");
      } finally {
        if (active) setLoadingData(false);
      }
    };
    void load();
    return () => { active = false; };
  }, [location.latitude, location.longitude, location.isSet]);

  const handleSearch = useCallback(() => {
    const q = searchQuery.trim();
    router.push(q ? `/providers?search=${encodeURIComponent(q)}` : "/providers");
  }, [searchQuery, router]);

  return (
    <div className="fade-up">

      {/* Hero Section */}
      <section className="relative overflow-hidden rounded-[20px] mb-6">
        <div className="absolute inset-0 bg-gradient-to-br from-purple-50/90 via-white to-violet-50/70" />
        <div className="absolute top-[-80px] right-[-60px] w-[350px] h-[350px] bg-gradient-to-bl from-purple-200/20 to-transparent rounded-full blur-3xl" />
        <div className="absolute bottom-[-40px] left-[-40px] w-[250px] h-[250px] bg-gradient-to-tr from-violet-200/15 to-transparent rounded-full blur-3xl" />

        <div className="relative px-5 py-7 text-center sm:px-8">
          <div className="inline-flex items-center gap-2 bg-white/90 backdrop-blur-sm border border-purple-100/80 rounded-full px-3.5 py-1.5 mb-3 shadow-sm">
            <Sparkles size={14} className="text-[var(--primary)]" />
            <span className="text-sm font-bold text-[var(--primary)]">Welcome back, {user?.name?.split(" ")[0] ?? "there"}</span>
          </div>

          <h1 className="text-[clamp(1.75rem,4vw,2.5rem)] font-extrabold text-slate-900 leading-[1.1] tracking-tight mb-3">
            Find the right professional{" "}
            <span className="bg-gradient-to-r from-[#6D28FF] via-[#8B5CF6] to-[#A855F7] bg-clip-text text-transparent">near you</span>
          </h1>
          <p className="text-sm sm:text-base text-slate-500 leading-relaxed max-w-lg mx-auto mb-5">
            Browse categories, discover services, and book verified professionals.
          </p>

          {/* Search Bar */}
          <div className="max-w-xl mx-auto">
            <div className="flex items-center gap-2 bg-white border-2 border-slate-200/80 rounded-[18px] p-2 pl-5 shadow-[0_8px_32px_rgba(109,40,255,0.06)] focus-within:border-purple-400 focus-within:shadow-[0_12px_40px_rgba(109,40,255,0.1)] transition-all">
              <Search size={20} className="text-slate-400 shrink-0" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSearch()}
                placeholder={SEARCH_EXAMPLES[placeholderIdx]}
                className="flex-1 bg-transparent outline-none text-sm text-slate-900 placeholder:text-slate-400 py-2"
              />
              <button onClick={handleSearch} className="shrink-0 inline-flex items-center gap-1.5 bg-gradient-to-r from-[#6D28FF] to-[#8B5CF6] text-white rounded-[12px] px-5 py-2.5 text-sm font-bold shadow-md shadow-purple-500/15 hover:shadow-lg transition-all">
                Search <ArrowRight size={14} />
              </button>
            </div>
          </div>

        </div>
      </section>

      {dataError && (
        <div className="bg-red-50 border border-red-100 rounded-2xl px-5 py-3.5 text-sm font-semibold text-red-700 mb-6">{dataError}</div>
      )}

      {/* Content */}
      <div className="space-y-7">
          {/* Categories */}
          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-extrabold text-slate-900 tracking-tight">Browse Categories</h2>
              <Link href="/categories" className="text-sm font-bold text-[var(--primary)] hover:text-purple-700 flex items-center gap-1 group">
                View all <ArrowRight size={13} className="group-hover:translate-x-0.5 transition-transform" />
              </Link>
            </div>

            {loadingData ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-5 gap-3">
                {Array.from({ length: 8 }).map((_, i) => (
                  <div key={i} className="bg-white rounded-[16px] border border-slate-100 p-4 flex flex-col items-center gap-3">
                    <div className="w-12 h-12 rounded-xl skeleton" />
                    <div className="w-16 h-3 rounded-lg skeleton" />
                  </div>
                ))}
              </div>
            ) : categories.length === 0 ? (
              <div className="rounded-[16px] border-2 border-dashed border-slate-200 bg-white p-8 text-center">
                <Sparkles size={24} className="text-purple-400 mx-auto mb-3" />
                <p className="font-bold text-slate-600">No categories available</p>
