                      <p style={{ fontWeight: 700, color: "#4f46e5", fontSize: "1.0625rem" }}>
                        {pro.price !== null ? `₹${pro.price}` : "Quote"}<span style={{ fontSize: "0.75rem", color: "#94a3b8", fontWeight: 500 }}> starting</span>
