  },
} as const;

type StatusKey = keyof typeof STATUS_CONFIG;

interface StatusData {
  status: StatusKey;
  rejectionReason: string | null;
  rejectionReasonCode: string | null;
  adminRemarks: string | null;
  rejectedAt: string | null;
  submittedAt?: string;
  updatedAt?: string;
}

// ─── Helper: format date nicely ───────────────────────────────────────────────
function formatDate(iso: string | null | undefined) {
  if (!iso) return null;
  return new Intl.DateTimeFormat("en-IN", {
    day: "numeric",
    month: "long",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso));
}

export default function ProviderStatusPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [statusData, setStatusData] = useState<StatusData | null>(null);

  const { isAuthenticated, role } = useSelector((state: RootState) => state.auth);

  useEffect(() => {
    if (!isAuthenticated || role !== "provider") {
      router.replace("/provider-portal/login");
      return;
    }

    const fetchStatus = async () => {
      try {
        const res = await providerService.getApplicationStatus();
        const data = res.data.data;

        setStatusData({
          status: (data.status as StatusKey) || "pending",
          rejectionReason: data.rejectionReason ?? null,
          rejectionReasonCode: (data as any).rejectionReasonCode ?? null,
          adminRemarks: (data as any).adminRemarks ?? null,
          rejectedAt: (data as any).rejectedAt ?? null,
          submittedAt: (data as any).submittedAt,
          updatedAt: (data as any).updatedAt,
        });
      } catch (err) {
        toast.error(getErrorMessage(err) || "Failed to fetch status");
      } finally {
        setLoading(false);
      }
    };

    fetchStatus();
  }, [isAuthenticated, role, router]);

